// 处理更新结果并进行详细分析
const healthResponse = $('check-api-health').first().json;
const updateResponse = $input.first().json;
const startTime = $('init-update-process').first().json.start_time;

const endTime = new Date().toISOString();
const duration = Math.round((new Date(endTime) - new Date(startTime)) / 1000);

// 分析API健康状态
const apiHealthy = healthResponse && (healthResponse.status === 'ok' || healthResponse.status === 'healthy');

// 分析更新结果
let updateStatus = 'unknown';
let summary = '';
let recommendations = [];

if (updateResponse && typeof updateResponse === 'object') {
  const { added = 0, updated = 0, total = 0, message = '' } = updateResponse;

  if (total > 0) {
    updateStatus = 'success';
    summary = `✅ 股票数据更新成功！\n` +
              `📊 统计信息:\n` +
              `  - 新增股票: ${added} 只\n` +
              `  - 更新股票: ${updated} 只\n` +
              `  - 处理总数: ${total} 只\n` +
              `⏱️ 执行时间: ${duration} 秒`;

    // 生成建议
    if (added > 100) {
      recommendations.push('🆕 发现大量新股票，建议检查是否有新上市股票');
    }
    if (updated > total * 0.8) {
      recommendations.push('🔄 大部分股票信息已更新，数据源活跃');
    }
    if (total < 3000) {
      recommendations.push('⚠️ 股票总数较少，可能存在数据获取问题');
    }
  } else {
    updateStatus = 'warning';
    summary = `⚠️ 股票数据更新完成，但没有变化\n` +
              `⏱️ 执行时间: ${duration} 秒`;
    recommendations.push('🔍 建议检查数据源是否正常');
  }
} else {
  updateStatus = 'error';
  summary = `❌ 股票数据更新失败！\n` +
            `⏱️ 执行时间: ${duration} 秒\n` +
            `🐛 错误信息: ${JSON.stringify(updateResponse)}`;
  recommendations.push('🚨 需要检查API接口和数据源连接');
  recommendations.push('📋 查看后端日志获取详细错误信息');
}

// 添加API健康状态到摘要
if (!apiHealthy) {
  summary += `\n⚠️ API健康检查异常: ${JSON.stringify(healthResponse)}`;
  recommendations.push('🏥 检查后端服务健康状态');
}

console.log(`Manual stock update completed: ${updateStatus}`);
console.log(summary);

return {
  json: {
    operation: 'manual_stock_update',
    status: updateStatus,
    api_healthy: apiHealthy,
    summary: summary,
    recommendations: recommendations,
    timing: {
      start_time: startTime,
      end_time: endTime,
      duration_seconds: duration
    },
    data: {
      added: updateResponse?.added || 0,
      updated: updateResponse?.updated || 0,
      total: updateResponse?.total || 0
    },
    raw_responses: {
      health_check: healthResponse,
      update_result: updateResponse
    }
  }
};

// 执行数据验证测试
const testSymbols = {
  '平安银行': '000001',
  '万科A': '000002', 
  '浦发银行': '600000',
  '特锐德': '300001',
  '中国石油': '601857',
  '贵州茅台': '600519'
};

const validationResults = [];
let successCount = 0;

for (const [name, symbol] of Object.entries(testSymbols)) {
  try {
    const response = await this.helpers.httpRequest({
      method: 'GET',
      url: `http://localhost:8000/api/v1/stocks/${symbol}`,
      headers: {
        'Accept': 'application/json'
      },
      timeout: 5000
    });

    if (response && response.symbol === symbol) {
      validationResults.push({
        expected_name: name,
        symbol: symbol,
        actual_name: response.name,
        status: '✅ 成功',
        pinyin_short: response.name_pinyin_short,
        exchange: response.exchange,
        market: response.market
      });
      successCount++;
    } else {
      validationResults.push({
        expected_name: name,
        symbol: symbol,
        status: '❌ 数据异常',
        error: '返回数据不匹配'
      });
    }
  } catch (error) {
    validationResults.push({
      expected_name: name,
      symbol: symbol,
      status: '❌ 请求失败',
      error: error.message
    });
  }

  // 避免请求过快
  await new Promise(resolve => setTimeout(resolve, 200));
}

// 测试搜索功能
const searchTests = [
  { query: '000001', type: '股票代码' },
  { query: 'PAYH', type: '拼音首字母' },
  { query: '平安', type: '股票名称' }
];

const searchResults = [];

for (const test of searchTests) {
  try {
    const response = await this.helpers.httpRequest({
      method: 'GET',
      url: `http://localhost:8000/api/v1/stocks/search?q=${encodeURIComponent(test.query)}&limit=5`,
      headers: {
        'Accept': 'application/json'
      },
      timeout: 5000
    });

    if (response && response.results && Array.isArray(response.results)) {
      searchResults.push({
        query: test.query,
        type: test.type,
        status: '✅ 成功',
        result_count: response.results.length,
        first_result: response.results[0]?.name || 'N/A'
      });
    } else {
      searchResults.push({
        query: test.query,
        type: test.type,
        status: '❌ 无结果',
        result_count: 0
      });
    }
  } catch (error) {
    searchResults.push({
      query: test.query,
      type: test.type,
      status: '❌ 请求失败',
      error: error.message
    });
  }

  await new Promise(resolve => setTimeout(resolve, 200));
}

const validationScore = Math.round((successCount / Object.keys(testSymbols).length) * 100);
const searchScore = Math.round((searchResults.filter(r => r.status.includes('成功')).length / searchTests.length) * 100);
const overallScore = Math.round((validationScore + searchScore) / 2);

console.log(`Data validation completed: ${successCount}/${Object.keys(testSymbols).length} stocks verified`);
console.log(`Search validation completed: ${searchScore}% success rate`);

return {
  json: {
    validation_summary: {
      overall_score: overallScore,
      stock_data_score: validationScore,
      search_function_score: searchScore,
      total_tests: Object.keys(testSymbols).length + searchTests.length
    },
    stock_validation: {
      success_count: successCount,
      total_tested: Object.keys(testSymbols).length,
      results: validationResults
    },
    search_validation: {
      success_count: searchResults.filter(r => r.status.includes('成功')).length,
      total_tested: searchTests.length,
      results: searchResults
    },
    validation_time: new Date().toISOString()
  }
};

// 生成最终报告
const updateResult = $('analyze-results').first().json;
const validationResult = $input.first().json;

const reportTime = new Date().toLocaleString('zh-CN', {
  timeZone: 'Asia/Shanghai',
  year: 'numeric',
  month: '2-digit', 
  day: '2-digit',
  hour: '2-digit',
  minute: '2-digit',
  second: '2-digit'
});

// 构建详细报告
let report = `📈 NewsTrader 股票数据更新报告\n`;
report += `🕐 执行时间: ${reportTime}\n`;
report += `⚡ 执行方式: 手动触发\n\n`;

// 更新结果摘要
report += `📊 数据更新结果:\n`;
report += updateResult.summary + '\n\n';

// 数据质量验证
report += `🔍 数据质量验证:\n`;
report += `  - 综合评分: ${validationResult.validation_summary.overall_score}/100\n`;
report += `  - 股票数据: ${validationResult.validation_summary.stock_data_score}/100\n`;
report += `  - 搜索功能: ${validationResult.validation_summary.search_function_score}/100\n\n`;

// 详细验证结果
report += `📋 详细验证结果:\n`;
validationResult.stock_validation.results.forEach((result, index) => {
  report += `  ${index + 1}. ${result.expected_name} (${result.symbol}): ${result.status}\n`;
  if (result.actual_name && result.pinyin_short) {
    report += `     名称: ${result.actual_name}, 拼音: ${result.pinyin_short}\n`;
  }
});

report += '\n🔎 搜索功能测试:\n';
validationResult.search_validation.results.forEach((result, index) => {
  report += `  ${index + 1}. ${result.type}搜索 "${result.query}": ${result.status}`;
  if (result.result_count > 0) {
    report += ` (找到${result.result_count}个结果)`;
  }
  report += '\n';
});

// 建议和警告
if (updateResult.recommendations && updateResult.recommendations.length > 0) {
  report += '\n💡 建议:\n';
  updateResult.recommendations.forEach((rec, index) => {
    report += `  ${index + 1}. ${rec}\n`;
  });
}

// 系统状态
report += '\n🏥 系统状态:\n';
report += `  - API服务: ${updateResult.api_healthy ? '✅ 正常' : '❌ 异常'}\n`;
report += `  - 数据库连接: ${validationResult.validation_summary.overall_score > 50 ? '✅ 正常' : '❌ 异常'}\n`;

// 下次更新提醒
report += '\n📅 下次自动更新: 每周日凌晨2:00\n';
report += '🔧 手动更新: 访问 n8n 界面执行此工作流\n';

console.log('='.repeat(60));
console.log('NewsTrader 股票数据更新报告');
console.log('='.repeat(60));
console.log(report);
console.log('='.repeat(60));

return {
  json: {
    report_type: 'manual_stock_update_complete',
    execution_time: reportTime,
    update_status: updateResult.status,
    validation_score: validationResult.validation_summary.overall_score,
    detailed_report: report,
    summary: {
      stocks_processed: updateResult.data.total,
      execution_duration: updateResult.timing.duration_seconds,
      api_healthy: updateResult.api_healthy,
      data_quality_score: validationResult.validation_summary.overall_score
    }
  }
};
